// ---- Q1_0 row-parallel 64x1 (F4d) -----------------------------------------
// lane j = row j; per column ONE vlm mask load + vsub.vx/vadd.vx,mu = net
// +-y. Zero reductions. zve32f only: fp16 scales are expanded with integer
// bit math (no zvfh), int16 group sums are widened with vsext+vfcvt (no
// vfwcvt.f.x.v - some RTLs reject it). LMUL adapts to VLEN so the 64 fp32
// accumulator lanes exactly fill the machine:
//   VLEN=512 : i16 m2 / f32 m4      VLEN>=1024: i16 m1 / f32 m2

#if defined(__riscv_v_intrinsic)

// Software prefetch of upcoming weight blocks. The gemv/gemm inner loop streams
// block_q1_0x64 sequentially (1152 B = 18 cache lines each); the HW prefetcher
// on this core is shallow (L3C_PFP_LINE_NUM=0, D$ 4 entries), so it cannot run
// far enough ahead to hide the L3/DRAM miss latency that makes the kernel
// load-bound. Pull the block Q1_PREFETCH_DIST ahead into cache explicitly.
// Pure hint: results are unchanged. Needs -march=..._zicbop (else
// __builtin_prefetch is a nop); Q1_PREFETCH_DIST=0 disables it entirely.
// Default 1 (measured best on ax46mpv_fpga_l3: 2.14M -> 1.39M cyc on the K=51
// V-proj node, 1.54x; distances 2/4 were worse - one 18-line block ahead
// already hides the L3/DRAM latency, further lookahead only adds cache/MSHR
// pressure). Other cores can override at build time.
//
// always_inline is load-bearing, not a hint: a prefetch has no observable side
// effect, so whenever the compiler leaves this helper out of line ipa-pure-const
// marks it pure and DCE then deletes every call - no warning, no prefetch left,
// and results stay correct so no test notices. GCC 14.2 does exactly that at
// -Os (CMake MinSizeRel), which cost the whole optimization there. Verify with
// check-prefetch.sh in the repo root: it counts prefetch.r per entry point.
#ifndef Q1_PREFETCH_DIST
#define Q1_PREFETCH_DIST 1
#endif
static inline __attribute__((always_inline))
void q1_prefetch_block(const block_q1_0x64 * bx, int l, int nb) {
#if Q1_PREFETCH_DIST > 0
    const int t = l + Q1_PREFETCH_DIST;
    if (t < nb) {
        const char * p = (const char *) &bx[t];
        for (size_t o = 0; o < sizeof(block_q1_0x64); o += 64) {
            __builtin_prefetch(p + o, 0, 3);
        }
    }
#else
    (void) bx; (void) l; (void) nb;
#endif
}

// exact for normals/+-0; q1_0 scales never carry fp16 subnormals
static inline vfloat32m4_t q1_expand_fp16_64_m4(const ggml_half * p) {
    const size_t vl = 64;
    const vuint32m4_t hz   = __riscv_vzext_vf2_u32m4(__riscv_vle16_v_u16m2((const uint16_t *) p, vl), vl);
    const vuint32m4_t sign = __riscv_vsll_vx_u32m4(__riscv_vand_vx_u32m4(hz, 0x8000, vl), 16, vl);
    vuint32m4_t       mag  = __riscv_vadd_vx_u32m4(
        __riscv_vsll_vx_u32m4(__riscv_vand_vx_u32m4(hz, 0x7FFF, vl), 13, vl), (uint32_t) 112 << 23, vl);
    const vbool8_t ez = __riscv_vmseq_vx_u32m4_b8(__riscv_vand_vx_u32m4(hz, 0x7C00, vl), 0, vl);
    mag               = __riscv_vmerge_vxm_u32m4(mag, 0, ez, vl);
    return __riscv_vreinterpret_v_u32m4_f32m4(__riscv_vor_vv_u32m4(sign, mag, vl));
}

static inline vfloat32m2_t q1_expand_fp16_64_m2(const ggml_half * p) {
    const size_t vl = 64;
    const vuint32m2_t hz   = __riscv_vzext_vf2_u32m2(__riscv_vle16_v_u16m1((const uint16_t *) p, vl), vl);
    const vuint32m2_t sign = __riscv_vsll_vx_u32m2(__riscv_vand_vx_u32m2(hz, 0x8000, vl), 16, vl);
    vuint32m2_t       mag  = __riscv_vadd_vx_u32m2(
        __riscv_vsll_vx_u32m2(__riscv_vand_vx_u32m2(hz, 0x7FFF, vl), 13, vl), (uint32_t) 112 << 23, vl);
    const vbool16_t ez = __riscv_vmseq_vx_u32m2_b16(__riscv_vand_vx_u32m2(hz, 0x7C00, vl), 0, vl);
    mag                = __riscv_vmerge_vxm_u32m2(mag, 0, ez, vl);
    return __riscv_vreinterpret_v_u32m2_f32m2(__riscv_vor_vv_u32m2(sign, mag, vl));
}

// ---- Q1_VD4DOT: the same row-parallel gemv on nds.vd4dots.vv (XAndesVDot) --
// Needs the Q1_VD4DOT sign-plane order (repack.h q1_0x64_sign_bit) and
// -march=..._xandesvdot. Only the VLEN>=1024 shape is implemented: e32/m2 is
// then exactly 64 i32 lanes = 64 rows, and the same register group seen as i8
// is 256 bytes = 64 rows x 4 columns, which is the operand shape the
// instruction consumes. Everything else falls through to the generic kernel.
#if defined(Q1_VD4DOT) && Q1_VD4DOT

// vd[lane] += sum_{k<4} vs1[4*lane+k] * vs2[4*lane+k], int8 x int8 into i32.
// GCC 14.2 has no intrinsic, so this is inline asm - and that shapes the whole
// helper. Two consequences drive the design, both measured, both gated by
// ./check-vd4dots.sh:
//
// 1. vtype churn (F9). GCC cannot see inside an asm block, so it assumes every
//    block left vtype unknown and re-issues its own vsetvli before the next
//    intrinsic. A one-dot block therefore costs TWO vsetvli, and the kernels
//    also alternate between the byte view (mask load, sign expand) and the
//    32-bit view (broadcast, dot) - 4 vsetvli per dot in the first version,
//    40% of the gemv inner loop, none of it arithmetic. Grouping the two
//    widths in the SOURCE is not enough: the scheduler interleaves them again.
//    So everything at e32 lives inside one block - the broadcasts too - which
//    leaves GCC only e8 work to schedule and pays one vsetvli per four dots.
//
// 2. The broadcast must stay vmv.v.x. Handed the intrinsic, GCC contracts
//    "load a word, splat it" into `vlse32.v vd,(rs1),zero`, and a stride-0
//    strided load is element-serial on this core - 18x slower. Taking the
//    activation quads as plain uint32 GPRs and spelling the splat out here
//    makes that contraction impossible by construction.
//
// Two scratch vectors, not four, so the four dots still overlap while the
// register budget stays clear of the 4 accumulators the gemm needs.

// gemv: four (weight, activation) pairs chained into one accumulator
static inline vint32m2_t q1_vd4dots_x4_m2(vint32m2_t acc,
        vint8m2_t w0, vint8m2_t w1, vint8m2_t w2, vint8m2_t w3,
        uint32_t u0, uint32_t u1, uint32_t u2, uint32_t u3) {
    vint8m2_t s0, s1;
    asm volatile(
        "vsetvli t0, zero, e32, m2, ta, ma\n\t"
        "vmv.v.x %[s0], %[u0]\n\t"
        "vmv.v.x %[s1], %[u1]\n\t"
        "nds.vd4dots.vv %[acc], %[w0], %[s0]\n\t"
        "nds.vd4dots.vv %[acc], %[w1], %[s1]\n\t"
        "vmv.v.x %[s0], %[u2]\n\t"
        "vmv.v.x %[s1], %[u3]\n\t"
        "nds.vd4dots.vv %[acc], %[w2], %[s0]\n\t"
        "nds.vd4dots.vv %[acc], %[w3], %[s1]"
        : [acc] "+vr" (acc), [s0] "=&vr" (s0), [s1] "=&vr" (s1)
        : [w0] "vr" (w0), [w1] "vr" (w1), [w2] "vr" (w2), [w3] "vr" (w3),
          [u0] "r" (u0), [u1] "r" (u1), [u2] "r" (u2), [u3] "r" (u3)
        : "t0");
    return acc;
}

// gemm: one weight vector against the four output rows of the M-tile
static inline void q1_vd4dots_4acc_m2(vint32m2_t * acc0, vint32m2_t * acc1,
        vint32m2_t * acc2, vint32m2_t * acc3, vint8m2_t w,
        uint32_t u0, uint32_t u1, uint32_t u2, uint32_t u3) {
    vint8m2_t s0, s1;
    asm volatile(
        "vsetvli t0, zero, e32, m2, ta, ma\n\t"
        "vmv.v.x %[s0], %[u0]\n\t"
        "vmv.v.x %[s1], %[u1]\n\t"
        "nds.vd4dots.vv %[a0], %[w], %[s0]\n\t"
        "nds.vd4dots.vv %[a1], %[w], %[s1]\n\t"
        "vmv.v.x %[s0], %[u2]\n\t"
        "vmv.v.x %[s1], %[u3]\n\t"
        "nds.vd4dots.vv %[a2], %[w], %[s0]\n\t"
        "nds.vd4dots.vv %[a3], %[w], %[s1]"
        : [a0] "+vr" (*acc0), [a1] "+vr" (*acc1),
          [a2] "+vr" (*acc2), [a3] "+vr" (*acc3),
          [s0] "=&vr" (s0), [s1] "=&vr" (s1)
        : [w] "vr" (w),
          [u0] "r" (u0), [u1] "r" (u1), [u2] "r" (u2), [u3] "r" (u3)
        : "t0");
}

static void q1_gemv_64_vd4dot_vl1024(int n, float * s, const void * vx, const block_q8_0 * a_ptr, int nc) {
    const int    nb   = n / QK1_0;
    const int    ng   = n / QK8_0;   // q8 groups per row
    const size_t vl32 = 64;          // i32 lanes  = rows
    const size_t vl8  = 64 * 4;      // i8  lanes  = rows x 4 columns

    // The dot needs 4 consecutive activation quants broadcast as one 32-bit
    // element, but block_q8_0 puts qs at struct offset 2, so every other group
    // is 2 mod 4 and this core faults on a misaligned 32-bit vector element
    // load. Restage the quants once per call through vector BYTE ld/st (no
    // alignment rule at EEW=8); the nc/64 row tiles below all reuse the copy.
    int8_t * aq = (int8_t *) __builtin_alloca((size_t) ng * QK8_0);
    for (int g = 0; g < ng; ++g) {
        __riscv_vse8_v_i8m1(aq + (size_t) g * QK8_0, __riscv_vle8_v_i8m1(a_ptr[g].qs, QK8_0), QK8_0);
    }

    const vint8m2_t vneg1 = __riscv_vmv_v_x_i8m2(-1, vl8);

    for (int x = 0; x < nc / 64; ++x) {
        const block_q1_0x64 * bx = (const block_q1_0x64 *) vx + (size_t) x * nb;
        vfloat32m2_t sumf = __riscv_vfmv_v_f_f32m2(0.0f, vl32);
        for (int l = 0; l < nb; ++l) {
            q1_prefetch_block(bx, l, nb);
            const vfloat32m2_t dx     = q1_expand_fp16_64_m2(bx[l].d);
            const uint8_t *    planes = (const uint8_t *) bx[l].qs;
            vfloat32m2_t       facc   = __riscv_vfmv_v_f_f32m2(0.0f, vl32);
            for (int k = 0; k < QK1_0 / QK8_0; ++k) {
                const int        g  = l * (QK1_0 / QK8_0) + k;
                const uint32_t * aw = (const uint32_t *) (aq + (size_t) g * QK8_0);
                vint32m2_t       acc = __riscv_vmv_v_x_i32m2(0, vl32);
                // 8 column quads, taken 4 at a time: all the e8 work (mask
                // load + sign expand) first, then all the e32 work (broadcast
                // + dot), so one vsetvli covers each half instead of one per
                // step. Interleaving them is what cost 4 vsetvli per dot.
                for (int q = 0; q < QK8_0 / 4; q += 4) {
                    const uint8_t * p = planes + (size_t) (k * (QK8_0 / 4) + q) * 32;
                    const vint8m2_t w0 = __riscv_vmerge_vxm_i8m2(vneg1, 1, __riscv_vlm_v_b4(p +  0, vl8), vl8);
                    const vint8m2_t w1 = __riscv_vmerge_vxm_i8m2(vneg1, 1, __riscv_vlm_v_b4(p + 32, vl8), vl8);
                    const vint8m2_t w2 = __riscv_vmerge_vxm_i8m2(vneg1, 1, __riscv_vlm_v_b4(p + 64, vl8), vl8);
                    const vint8m2_t w3 = __riscv_vmerge_vxm_i8m2(vneg1, 1, __riscv_vlm_v_b4(p + 96, vl8), vl8);
                    acc = q1_vd4dots_x4_m2(acc, w0, w1, w2, w3,
                        aw[q + 0], aw[q + 1], aw[q + 2], aw[q + 3]);
                }
                facc = __riscv_vfmacc_vf_f32m2(facc, GGML_CPU_FP16_TO_FP32(a_ptr[g].d),
                    __riscv_vfcvt_f_x_v_f32m2(acc, vl32), vl32);
            }
            sumf = __riscv_vfmacc_vv_f32m2(sumf, dx, facc, vl32);
        }
        __riscv_vse32_v_f32m2(s + (size_t) x * 64, sumf, vl32);
    }
}

// ---- Q1_VD4DOT gemm: 4 output rows per pass, weight stream read once x4 ----
// Same dot and the same weight stream as the gemv above; only the activation
// side is new. The x4 activation block stores qs[c*4 + m] (blck_size_interleave
// 1), but the dot wants row m's columns c..c+3 as ONE 32-bit element, which is
// a stride-4 gather. So de-interleave the whole row tile once up front: read
// the block as 32 u32 elements and peel the four byte lanes apart with vnsrl
// (u32 -> 2x u16 -> 4x u8). 6 shifts + 4 stores per 32 columns, reused by every
// column tile - under 1% of the inner loop - and unlike vlse8 or a segment load
// it is plain RVV that cannot turn element-serial.
// The u32 view is legal here: block_q8_0x4 keeps qs 4-byte aligned (d[4] is
// 8 B, sizeof is 136), unlike block_q8_0 whose qs sits at offset 2 - that is
// why the gemv must restage through byte ld/st and this kernel need not.
//
// Register budget at e32/m2 is why the per-block float accumulator of the other
// kernels is gone: 4 sumf + 4 acc + dx + w + a + vneg1 already takes 24 of 32
// vector registers, and one facc per row would not fit. Folding the activation
// scale into dx instead costs one vfmul per group and is the same sum:
//   sum_l dx * (sum_k da[k]*acc[k])  ==  sum_l sum_k (dx*da[k]) * acc[k]
static void q1_gemm_64_vd4dot_vl1024(int n, float * s, size_t bs, const void * vx,
                                     const block_q8_0x4 * vy, int nr, int nc) {
    const int    nb   = n / QK1_0;
    const int    ng   = n / QK8_0;   // q8 groups per row
    const size_t vl32 = 64;          // i32 lanes  = rows
    const size_t vl8  = 64 * 4;      // i8  lanes  = rows x 4 columns

    // the row tile's activation quants, de-interleaved: aq[m * n + column]
    int8_t * aq = (int8_t *) __builtin_alloca(4 * (size_t) n);

    const vint8m2_t vneg1 = __riscv_vmv_v_x_i8m2(-1, vl8);

    for (int y = 0; y < nr / 4; ++y) {
        const block_q8_0x4 * a_ptr = vy + (size_t) y * ng;

        for (int g = 0; g < ng; ++g) {
            const vuint32m1_t  q  = __riscv_vle32_v_u32m1((const uint32_t *) a_ptr[g].qs, QK8_0);
            const vuint16mf2_t lo = __riscv_vnsrl_wx_u16mf2(q,  0, QK8_0);  // rows 0,1
            const vuint16mf2_t hi = __riscv_vnsrl_wx_u16mf2(q, 16, QK8_0);  // rows 2,3
            uint8_t * dst = (uint8_t *) aq + (size_t) g * QK8_0;
            __riscv_vse8_v_u8mf4(dst + 0 * (size_t) n, __riscv_vnsrl_wx_u8mf4(lo, 0, QK8_0), QK8_0);
            __riscv_vse8_v_u8mf4(dst + 1 * (size_t) n, __riscv_vnsrl_wx_u8mf4(lo, 8, QK8_0), QK8_0);
            __riscv_vse8_v_u8mf4(dst + 2 * (size_t) n, __riscv_vnsrl_wx_u8mf4(hi, 0, QK8_0), QK8_0);
            __riscv_vse8_v_u8mf4(dst + 3 * (size_t) n, __riscv_vnsrl_wx_u8mf4(hi, 8, QK8_0), QK8_0);
        }

        for (int x = 0; x < nc / 64; ++x) {
            const block_q1_0x64 * bx = (const block_q1_0x64 *) vx + (size_t) x * nb;
            vfloat32m2_t sumf0 = __riscv_vfmv_v_f_f32m2(0.0f, vl32);
            vfloat32m2_t sumf1 = sumf0, sumf2 = sumf0, sumf3 = sumf0;
            for (int l = 0; l < nb; ++l) {
                q1_prefetch_block(bx, l, nb);
                const vfloat32m2_t dx     = q1_expand_fp16_64_m2(bx[l].d);
                const uint8_t *    planes = (const uint8_t *) bx[l].qs;
                for (int k = 0; k < QK1_0 / QK8_0; ++k) {
                    const int        g  = l * (QK1_0 / QK8_0) + k;
                    const uint32_t * a0 = (const uint32_t *) (aq + 0 * (size_t) n + (size_t) g * QK8_0);
                    const uint32_t * a1 = (const uint32_t *) (aq + 1 * (size_t) n + (size_t) g * QK8_0);
                    const uint32_t * a2 = (const uint32_t *) (aq + 2 * (size_t) n + (size_t) g * QK8_0);
                    const uint32_t * a3 = (const uint32_t *) (aq + 3 * (size_t) n + (size_t) g * QK8_0);
                    vint32m2_t acc0 = __riscv_vmv_v_x_i32m2(0, vl32);
                    vint32m2_t acc1 = acc0, acc2 = acc0, acc3 = acc0;
                    // the 4 output rows already share one weight vector, so
                    // one asm block covers all 4 dots and their vsetvli
                    for (int c = 0; c < QK8_0; c += 4) {
                        const vbool4_t  m = __riscv_vlm_v_b4(planes + (size_t) (k * (QK8_0 / 4) + c / 4) * 32, vl8);
                        const vint8m2_t w = __riscv_vmerge_vxm_i8m2(vneg1, 1, m, vl8);
                        q1_vd4dots_4acc_m2(&acc0, &acc1, &acc2, &acc3, w,
                            a0[c / 4], a1[c / 4], a2[c / 4], a3[c / 4]);
                    }
                    const ggml_half * ad = a_ptr[g].d;
                    sumf0 = __riscv_vfmacc_vv_f32m2(sumf0,
                        __riscv_vfmul_vf_f32m2(dx, GGML_CPU_FP16_TO_FP32(ad[0]), vl32),
                        __riscv_vfcvt_f_x_v_f32m2(acc0, vl32), vl32);
                    sumf1 = __riscv_vfmacc_vv_f32m2(sumf1,
                        __riscv_vfmul_vf_f32m2(dx, GGML_CPU_FP16_TO_FP32(ad[1]), vl32),
                        __riscv_vfcvt_f_x_v_f32m2(acc1, vl32), vl32);
                    sumf2 = __riscv_vfmacc_vv_f32m2(sumf2,
                        __riscv_vfmul_vf_f32m2(dx, GGML_CPU_FP16_TO_FP32(ad[2]), vl32),
                        __riscv_vfcvt_f_x_v_f32m2(acc2, vl32), vl32);
                    sumf3 = __riscv_vfmacc_vv_f32m2(sumf3,
                        __riscv_vfmul_vf_f32m2(dx, GGML_CPU_FP16_TO_FP32(ad[3]), vl32),
                        __riscv_vfcvt_f_x_v_f32m2(acc3, vl32), vl32);
                }
            }
            __riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 0) * bs + (size_t) x * 64, sumf0, vl32);
            __riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 1) * bs + (size_t) x * 64, sumf1, vl32);
            __riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 2) * bs + (size_t) x * 64, sumf2, vl32);
            __riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 3) * bs + (size_t) x * 64, sumf3, vl32);
        }
    }
}

