// ---- Q1_0 row-parallel 64x1 (F4d) -----------------------------------------
// lane j = row j. Per column: sign bit selects +-activation; int sums per
// 32-group, scaled by the q8 dy, then by the per-row q1 dx per block - the
// same two-level order as ggml_vec_dot_q1_0_q8_0, so results match closely.

void ggml_gemv_q1_0_64x1_q8_0_generic(int n, float * GGML_RESTRICT s, size_t bs, const void * GGML_RESTRICT vx, const void * GGML_RESTRICT vy, int nr, int nc) {
    const int qk = QK8_0;
    const int nb = n / QK1_0;
    assert(n % QK1_0 == 0);
    assert(nc % 64 == 0);
    UNUSED(bs); UNUSED(nr);

    const block_q8_0 * a_ptr = (const block_q8_0 *) vy;
    for (int x = 0; x < nc / 64; ++x) {
        const block_q1_0x64 * b_ptr = (const block_q1_0x64 *) vx + (size_t) x * nb;

        float sumf[64] = { 0.0f };
        for (int l = 0; l < nb; ++l) {
            float acc[64] = { 0.0f };
            for (int k = 0; k < QK1_0 / qk; ++k) {
                const block_q8_0 * ab = &a_ptr[l * (QK1_0 / qk) + k];
                const float dy = GGML_CPU_FP16_TO_FP32(ab->d);

                int sumi[64] = { 0 };
                const uint8_t * planes = (const uint8_t *) b_ptr[l].qs;
                for (int c = 0; c < qk; ++c) {
                    const int v = ab->qs[c];
                    for (int j = 0; j < 64; ++j) {
                        const int bi = q1_0x64_sign_bit(k * qk + c, j);
                        sumi[j] += ((planes[bi / 8] >> (bi % 8)) & 1) ? v : -v;
                    }
                }
                for (int j = 0; j < 64; ++j) {
                    acc[j] += dy * (float) sumi[j];
                }
            }
            for (int j = 0; j < 64; ++j) {
                sumf[j] += GGML_CPU_FP16_TO_FP32(b_ptr[l].d[j]) * acc[j];
            }
        }
        for (int j = 0; j < 64; ++j) {
            s[x * 64 + j] = sumf[j];
        }
    }
}

