            float sumf[4][64] = { { 0.0f } };
            for (int l = 0; l < nb; ++l) {
                float acc[4][64] = { { 0.0f } };
                for (int k = 0; k < QK1_0 / qk; ++k) {
                    const block_q8_0x4 * ab = &a_ptr[l * (QK1_0 / qk) + k];
                    float dy[4];
                    for (int m = 0; m < 4; ++m) {
