                    int sumi[4][64] = { { 0 } };
                    const uint8_t * planes = (const uint8_t *) b_ptr[l].qs;
                    for (int c = 0; c < qk; ++c) {
                        for (int m = 0; m < 4; ++m) {
                            const int v = ab->qs[c * 4 + m];
                            for (int j = 0; j < 64; ++j) {
