static int repack_q1_0_to_q1_0_64_bl(struct ggml_tensor * t, int interleave_block, const void * GGML_RESTRICT data, size_t data_size) {
    GGML_ASSERT(t->type == GGML_TYPE_Q1_0);
    GGML_ASSERT(interleave_block == 1);
    constexpr int nrows_interleaved = 64;

    block_q1_0x64 *      dst = (block_q1_0x64 *) t->data;
    const block_q1_0 * src = (const block_q1_0 *) data;
    const int nrow    = ggml_nrows(t);
    const int nblocks = t->ne[0] / QK1_0;

    GGML_ASSERT(data_size == (size_t) nrow * nblocks * sizeof(block_q1_0));

    if (t->ne[1] % nrows_interleaved != 0 || t->ne[0] % QK1_0 != 0) {
        return -1;
    }

    // sign planes are OR-accumulated bit by bit - start from zero
    memset(dst, 0, (size_t) (nrow / nrows_interleaved) * nblocks * sizeof(block_q1_0x64));

    for (int b = 0; b < nrow; b += nrows_interleaved) {
        block_q1_0x64 * out = dst + (size_t) (b / nrows_interleaved) * nblocks;
        for (int j = 0; j < nrows_interleaved; ++j) {
            const block_q1_0 * row = src + (size_t) (b + j) * nblocks;
            for (int ib = 0; ib < nblocks; ++ib) {
                out[ib].d[j] = row[ib].d;
                uint8_t * planes = (uint8_t *) out[ib].qs;
                for (int c = 0; c < QK1_0; ++c) {
                    const uint8_t bit = (row[ib].qs[c / 8] >> (c % 8)) & 1;
                    const int     bi  = q1_0x64_sign_bit(c, j);
                    planes[bi / 8] |= (uint8_t) (bit << (bi % 8));
                }
            }
        }
    }
    return 0;

    GGML_UNUSED(data_size);
}

